package net.officefloor.hq.app.claim;

/** A claim's status. It starts DRAFT; DRAFT opens to OPEN, OPEN settles to SETTLED (or, settled by a
 *  clerk above the clerk limit, to PENDING), PENDING is approved to SETTLED or rejected back to OPEN,
 *  and DRAFT, OPEN or PENDING voids to VOID. VOID is final; SETTLED is too, but for a steward voiding it
 *  soon after its settlement (see {@link VoidClaim}). */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** The status after moving to {@code to}; refused when this status does not allow it. */
    public ClaimStatus moveTo(ClaimStatus to) throws ClaimStatusException {
        boolean allowed = switch (to) {
            case OPEN -> this == DRAFT || this == PENDING;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT -> false;
        };
        if (!allowed) {
            throw new ClaimStatusException("A " + this + " claim cannot become " + to);
        }
        return to;
    }

    /** Whether a claim with this status is open: OPEN, or PENDING (awaiting a steward's approval). */
    public static boolean isOpen(String status) {
        return OPEN.name().equals(status) || PENDING.name().equals(status);
    }

    /** The audit event recorded when a claim moves to this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
        };
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.voidreason.VoidReasonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Voids a claim; an opened claim keeps its number (still never reused). Refused for a role the
 *  permission matrix does not let void. A SETTLED claim may be voided only by a steward, within
 *  {@link #SETTLED_DAYS} days of its settlement (its status log's SETTLED date) by the sheet's today:
 *  its frozen figure leaves every total (it is kept on the claim, and reported as reversed). While the
 *  sheet has void reasons, a void needs one of them ({@code reason}), kept on the claim; refused without. */
public class VoidClaim {
    public static final int SETTLED_DAYS = 7;

    public void move(@RequestParam(name = "by", required = false) String by,
            @RequestParam(name = "reason", required = false) String reason, @Val Claim claim,
            PeriodRepository periods, RoleRepository roles, SettingRepository settings,
            ClaimLogRepository log, SheetRepository sheets, VoidReasonRepository reasons)
            throws ClaimStatusException, PeriodClosedException, InvalidClaimException {
        String chosen = reason == null ? "" : reason.trim();
        if (reasons.any(claim.getSheetId())) {
            if (chosen.isEmpty() || !reasons.contains(claim.getSheetId(), chosen)) {
                throw new InvalidClaimException("A void needs a reason from the sheet's void reasons");
            }
            claim.setVoidReason(chosen);
        }
        if (ClaimStatus.SETTLED.name().equals(claim.getStatus())) {
            voidSettled(by, claim, periods, roles, log, sheets);
            return;
        }
        if (!Permissions.allows(claim.getSheetId(), by, Permissions.VOID, roles, settings)) {
            throw new ClaimStatusException("Your role may not void a claim");
        }
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        claim.setStatus(ClaimStatus.valueOf(claim.getStatus()).moveTo(ClaimStatus.VOID).name());
    }

    private static void voidSettled(String by, Claim claim, PeriodRepository periods, RoleRepository roles,
            ClaimLogRepository log, SheetRepository sheets) throws ClaimStatusException, PeriodClosedException {
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), by == null ? "" : by))) {
            throw new ClaimStatusException("Only a steward can void a SETTLED claim");
        }
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        LocalDate settledOn = log.settledOn(claim.getSheetId(), claim.getId());
        if (settledOn == null || sheets.today(claim.getSheetId()).isAfter(settledOn.plusDays(SETTLED_DAYS))) {
            throw new ClaimStatusException("A SETTLED claim can be voided only within " + SETTLED_DAYS
                    + " days of its settlement");
        }
        claim.setStatus(ClaimStatus.VOID.name());
        claim.setReversal(true);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Opens a claim, giving it its number (see {@link ClaimNumbers}) and recording who opened it.
 *  Refused for a role the permission matrix does not let open, and for a claim with an empty note
 *  whose due is above the note threshold in force on its date. */
public class OpenClaim {
    public void move(@RequestParam(name = "by", required = false) String by, @Val Claim claim,
            ClaimRepository claims, PeriodRepository periods, SettingRepository settings,
            SheetRepository sheets, RoleRepository roles, PersonRepository people, RateRepository rates)
            throws ClaimStatusException, PeriodClosedException {
        if (!Permissions.allows(claim.getSheetId(), by, Permissions.OPEN, roles, settings)) {
            throw new ClaimStatusException("Your role may not open a claim");
        }
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        ClaimStatus opened = ClaimStatus.valueOf(claim.getStatus()).moveTo(ClaimStatus.OPEN);
        requireNote(claim, people, rates, settings, sheets);
        claim.setStatus(opened.name());
        claim.setNumber(ClaimNumbers.next(claim, claims, periods, settings, sheets));
        claim.setOpenedBy(by == null ? "" : by);
    }

    /** Refuses opening a claim with an empty note whose due (null: n/a, never above) is above the
     *  sheet's note threshold in force on the claim's date; shared with {@link BulkOpenClaims}. */
    static void requireNote(Claim claim, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) throws ClaimStatusException {
        if (claim.getNote() != null && !claim.getNote().trim().isEmpty()) return;
        BigDecimal threshold = settings.noteThreshold(claim.getSheetId(), claim.getDate());
        if (threshold == null) return;
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        Rate rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()),
                LocalDate.parse(claim.getDate()));
        Dues.Late late = settings.late(claim.getSheetId(), sheets.today(claim.getSheetId()));
        String due = Dues.shown(claim, rate == null ? null : Dues.of(claim.getAmount(), rate.pct(),
                late.rounding(claim.getRoundDate())), settings.floor(claim.getSheetId()).on(claim.getDate()), late);
        if (due != null && new BigDecimal(due).compareTo(threshold) > 0) {
            throw new ClaimStatusException("A claim whose due is above the note threshold needs a note to be opened");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Write step after the claim is saved: logs the status it now has (see {@link ClaimLogRepository}). */
public class LogClaimStatus {
    public void log(@RequestParam(name = "by", required = false) String by, @Val Claim claim,
            ClaimLogRepository log) {
        log.record(claim, by);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a status change that went through is recorded. */
public class RecordClaimStatus {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Claim claim, PersonRepository people, Audit audit) {
        audit.record(line(ClaimStatus.valueOf(claim.getStatus()).event(), by, claim, people)
                + (ClaimStatus.SETTLED.name().equals(claim.getStatus()) ? due(claim) : "")
                + (claim.isReversal() ? reversed(claim) : "")
                + (ClaimStatus.VOID.name().equals(claim.getStatus()) && claim.getVoidReason() != null
                        ? " reason=" + claim.getVoidReason() : ""));
    }

    /** A claim line: the event, the sheet, the user, then the claim's person, amount, date and number. */
    static String line(String event, String by, Claim claim, PersonRepository people) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        return event + " sheet=" + claim.getSheetId()
                + " by=" + (by == null ? "" : by)
                + " person=" + (person == null ? "" : person.getName())
                + " amount=" + claim.getAmount() + " date=" + claim.getDate()
                + claim.getAuditNumber();
    }

    /** The reversed suffix of a voided SETTLED claim: the frozen figure that left the totals. */
    static String reversed(Claim claim) {
        return " reversed=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue());
    }

    /** The fixed due suffix of a settled claim. */
    static String due(Claim claim) {
        return " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue());
    }
}
package net.officefloor.hq.app.claim;

/** The claim's status does not allow the change (a SETTLED or VOID claim never changes), or the
 *  user may not make it (the one who opened a claim cannot settle it): refused and nothing is written. */
public class ClaimStatusException extends Exception {
    public ClaimStatusException(String message) {
        super(message);
    }
}
